parameters.jsCode:
const form = $('Lead Form').first().json;
const cfg = $('Config').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content ?? '{}';

let ai = {};
try { ai = JSON.parse(raw); } catch (e) { ai = {}; }

// Safety: if the AI returns something unexpected, default to "warm"
let score = String(ai.score || '').toLowerCase();
if (!['hot', 'warm', 'cold'].includes(score)) score = 'warm';

const fullName = String(form['Full Name'] || '').trim();
const parts = fullName.split(/\s+/);
const firstName = parts[0] || 'there';
const lastName = parts.slice(1).join(' ');

const fallbackReply = `Hi ${firstName},\n\nThanks for reaching out. I received your message and will get back to you shortly.\n\n${cfg.owner_name}`;

return [{
  json: {
    score,
    reason: String(ai.reason || 'No reason provided').slice(0, 300),
    reply: String(ai.reply_email || '').trim() || fallbackReply,
    firstName,
    lastName,
    fullName,
    email: String(form['Email'] || '').trim().toLowerCase(),
    phone: form['Phone'] || '',
    company: form['Company'] || '',
    need: form['What do you need help with?'] || '',
    budget: form['Budget'] || '',
    timeline: form['Timeline'] || ''
  }
}];

